dtsPropsFor.AppFrame:
/** Right-aligned header slot — e.g. a ConnectionIndicator or phase badge. */
headerRight?: React.ReactNode;
children: React.ReactNode;
className?: string;

dtsPropsFor.VerdictBadge:
/** Safety verdict (wire form, lowercase). Only allow/clamp/reject render a
 *  badge; recovery/fault/emergency_stop render nothing (modal/banner/phase). */
verdict: "allow" | "clamp" | "reject" | "recovery" | "fault" | "emergency_stop";
className?: string;

dtsPropsFor.ConnectionIndicator:
/** Stream liveness — drives the dot colour + label. */
status: "connecting" | "live" | "reconnecting" | "stale";
className?: string;

dtsPropsFor.LiveCurve:
/** Curve points. Temps in °C, RoR in °C/min, heat/fan in %. `null` = gap. */
points: Array<{
  /** Serve-elapsed seconds (the chart x-axis). */
  t: number;
  bean: number | null;
  env: number | null;
  ror: number | null;
  heat: number | null;
  fan: number | null;
}>;
/** Vertical event markers (T0 / dry end / first crack / drop / cooling). */
markers?: Array<{
  kind: "t0" | "dry_end" | "first_crack" | "drop" | "cooling";
  t: number;
  label: string;
}>;
/** Current roast phase — the preheat charge band shows in "preheating" only. */
phase?:
  | "idle"
  | "starting"
  | "preheating"
  | "roasting_pre_first_crack"
  | "development"
  | "cooling"
  | "complete"
  | "faulted"
  | "operator_recovery_required"
  | null;
/** Charge guidance band (°C); shown only while phase === "preheating". */
chargeBand?: { minC: number; maxC: number };
/** Controlled highlight time (serve-elapsed seconds); null clears it. */
highlightTime?: number | null;
/** Serve-elapsed seconds at T0/charge, for the charge-referenced roast-time axis. */
originSeconds?: number | null;
/** Series hidden by default (e.g. detail view may start with heat/fan off). */
initialHidden?: Array<"bean" | "env" | "ror" | "heat" | "fan">;
className?: string;
/** Chart height in px (default 420). */
height?: number;
